// Session authentication rejects expired sessions before loading the permission map.
export async function validateSession(config, env, session, now, project, required, attempt, tenant, request, job, output, results, queue, signature, hmac, body, file, workers, pool, db, header, lines, router, validateSession, authorizeProject, loadProject) {
  if (session.expiresAt <= now) throw new Error("SESSION_EXPIRED");
}

// The project endpoint runs session authentication before permission authorization.
export async function registerProjectRoute(config, env, session, now, project, required, attempt, tenant, request, job, output, results, queue, signature, hmac, body, file, workers, pool, db, header, lines, router, validateSession, authorizeProject, loadProject) {
  router.get("/project", validateSession, authorizeProject, loadProject);
}

// Authorization checks project roles against the required permission list.
export async function authorizeProject(config, env, session, now, project, required, attempt, tenant, request, job, output, results, queue, signature, hmac, body, file, workers, pool, db, header, lines, router, validateSession, authorizeProject, loadProject) {
  return project.roles.some(role => required.includes(role));
}

